import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.DpXDHk3d.js";const g=JSON.parse('{"title":"低压电工考证学习文档","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/readme.md","filePath":"electrician/low-voltage-electrician/readme.md","lastUpdated":1793095197000}'),l={name:"electrician/low-voltage-electrician/readme.md"};function d(o,a,c,n,h,s){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="低压电工考证学习文档" tabindex="-1">低压电工考证学习文档 <a class="header-anchor" href="#低压电工考证学习文档" aria-label="Permalink to &quot;低压电工考证学习文档&quot;">​</a></h1><blockquote><p>面向《特种作业操作证 · 低压电工作业》考证的系统化学习资料,覆盖理论机考与实操考核知识点,<strong>重点在理论</strong>。内容力求通俗易懂,概念讲解详细,适合零基础入门和考前复习。</p></blockquote><h2 id="什么是低压电工特种作业操作证" tabindex="-1">什么是低压电工特种作业操作证 <a class="header-anchor" href="#什么是低压电工特种作业操作证" aria-label="Permalink to &quot;什么是低压电工特种作业操作证&quot;">​</a></h2><p>特种作业操作证(俗称&quot;电工证&quot;、&quot;IC 卡证&quot;)是从事特种作业必须持有的上岗证,由<strong>应急管理部门</strong>(原安全生产监督管理部门)考核发证。低压电工是指从事 **1 kV 以下(不含 1 kV)**低压电气设备的安装、检修、运行、维护作业的人员。</p><ul><li><strong>证书样式</strong>:IC 卡式,全国通用</li><li><strong>有效期</strong>:6 年</li><li><strong>复审</strong>:每 3 年复审一次</li><li><strong>查验</strong>:证书真伪可在应急管理部官网查询</li></ul><h2 id="考试形式" tabindex="-1">考试形式 <a class="header-anchor" href="#考试形式" aria-label="Permalink to &quot;考试形式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>理论考试</td><td>计算机机考,约 100 题(单选 / 多选 / 判断),满分 100 分,<strong>80 分及格</strong></td></tr><tr><td>实操考核</td><td>现场操作 + 口述,考核仪表使用、电动机控制线路、安全操作、触电急救等</td></tr><tr><td>两科要求</td><td>理论和实操均合格,方可取得证书</td></tr></tbody></table><h2 id="如何使用本套文档" tabindex="-1">如何使用本套文档 <a class="header-anchor" href="#如何使用本套文档" aria-label="Permalink to &quot;如何使用本套文档&quot;">​</a></h2><ol><li><strong>按章节顺序学习</strong>:先打基础(第 1~4 章)→ 学设备与元器件(第 5~8 章)→ 学系统与安全(第 9~13 章)→ 最后看实操与应试(第 14 章)。</li><li>每节末尾设有「<strong>考点提示</strong>」和「<strong>自测练习</strong>」,先自己作答再对照参考答案。</li><li>高频考点章节(如 3.3 安全电压、9.2 接地形式、11.2 接地接零)建议反复复习。</li><li>结合真题练习:理解概念后再刷题,事半功倍。</li></ol><h2 id="目录总览" tabindex="-1">目录总览 <a class="header-anchor" href="#目录总览" aria-label="Permalink to &quot;目录总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>主题</th><th>学习重点</th></tr></thead><tbody><tr><td>01</td><td>安全生产法律法规</td><td>特种作业制度、复审周期、持证上岗</td></tr><tr><td>02</td><td>电工基础知识</td><td>电流电压电阻、欧姆定律、串并联、交流电</td></tr><tr><td>03</td><td>电气安全基础知识</td><td>触电危害、安全电压、安全标识</td></tr><tr><td>04</td><td>常用电工仪表</td><td>万用表、钳形表、兆欧表</td></tr><tr><td>05</td><td>常用低压电器</td><td>熔断器、断路器、接触器、继电器、漏电保护器</td></tr><tr><td>06</td><td>导线电缆与低压线路</td><td>导线型号、截面选择、敷设</td></tr><tr><td>07</td><td>变压器</td><td>原理、结构、运行维护</td></tr><tr><td>08</td><td>三相异步电动机</td><td>结构、原理、启动控制、维护</td></tr><tr><td>09</td><td>低压配电系统</td><td>接地形式 TN-S/TN-C/TT、配电箱、识图</td></tr><tr><td>10</td><td>电气照明</td><td>光源、线路安装、故障检修</td></tr><tr><td>11</td><td>防雷与接地</td><td>雷电防护、接地接零</td></tr><tr><td>12</td><td>电气防火防爆与触电急救</td><td>火灾预防、灭火、心肺复苏</td></tr><tr><td>13</td><td>安全作业操作规范</td><td>停电验电挂地线、安全用具、倒闸操作</td></tr><tr><td>14</td><td>实操考核与应试技巧</td><td>实操要点、机考答题技巧</td></tr></tbody></table><hr><h2 id="章节详情" tabindex="-1">章节详情 <a class="header-anchor" href="#章节详情" aria-label="Permalink to &quot;章节详情&quot;">​</a></h2><h3 id="_01-·-安全生产法律法规" tabindex="-1"><a href="/some-docs/electrician/low-voltage-electrician/01-chapter-1-an-quan-sheng-chan-fa-l-fa-gui/readme.html">01 · 安全生产法律法规</a> <a class="header-anchor" href="#_01-·-安全生产法律法规" aria-label="Permalink to &quot;[01 · 安全生产法律法规](/electrician/low-voltage-electrician/01-chapter-1-an-quan-sheng-chan-fa-l-fa-gui/readme)&quot;">​</a></h3><p>1.1 安全生产法律法规体系 · 1.2 特种作业人员管理制度 · 1.3 电工的职责与职业道德 · 1.4 违反安全规定的法律责任</p><h3 id="_02-·-电工基础知识" tabindex="-1"><a href="/some-docs/electrician/low-voltage-electrician/02-chapter-2-dian-gong-ji-chu-zhi-shi/readme.html">02 · 电工基础知识</a> <a class="header-anchor" href="#_02-·-电工基础知识" aria-label="Permalink to &quot;[02 · 电工基础知识](/electrician/low-voltage-electrician/02-chapter-2-dian-gong-ji-chu-zhi-shi/readme)&quot;">​</a></h3><p>2.1 电工基本概念 · 2.2 电路的组成 · 2.3 串联与并联电路 · 2.4 欧姆定律与电功率 · 2.5 交流电路基础 · 2.6 电与磁及电磁感应 · 2.7 常用电工名词与单位速查</p><h3 id="_03-·-电气安全基础知识" tabindex="-1"><a href="/some-docs/electrician/low-voltage-electrician/03-chapter-3-dian-qi-an-quan-ji-chu-zhi-shi/readme.html">03 · 电气安全基础知识</a> <a class="header-anchor" href="#_03-·-电气安全基础知识" aria-label="Permalink to &quot;[03 · 电气安全基础知识](/electrician/low-voltage-electrician/03-chapter-3-dian-qi-an-quan-ji-chu-zhi-shi/readme)&quot;">​</a></h3><p>3.1 电流对人体的危害 · 3.2 触电类型与触电方式 · 3.3 安全电压与安全电流 · 3.4 安全距离与安全防护 · 3.5 安全标识与警示标志</p><h3 id="_04-·-常用电工仪表" tabindex="-1"><a href="/some-docs/electrician/low-voltage-electrician/04-chapter-4-chang-yong-dian-gong-yi-biao/readme.html">04 · 常用电工仪表</a> <a class="header-anchor" href="#_04-·-常用电工仪表" aria-label="Permalink to &quot;[04 · 常用电工仪表](/electrician/low-voltage-electrician/04-chapter-4-chang-yong-dian-gong-yi-biao/readme)&quot;">​</a></h3><p>4.1 仪表基础知识 · 4.2 万用表 · 4.3 钳形电流表 · 4.4 兆欧表 · 4.5 电能表与接地电阻测量仪</p><h3 id="_05-·-常用低压电器" tabindex="-1"><a href="/some-docs/electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/readme.html">05 · 常用低压电器</a> <a class="header-anchor" href="#_05-·-常用低压电器" aria-label="Permalink to &quot;[05 · 常用低压电器](/electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/readme)&quot;">​</a></h3><p>5.1 低压电器概述与分类 · 5.2 熔断器 · 5.3 低压断路器 · 5.4 交流接触器 · 5.5 热继电器 · 5.6 中间继电器与时间继电器 · 5.7 主令电器 · 5.8 漏电保护器</p><h3 id="_06-·-导线电缆与低压线路" tabindex="-1"><a href="/some-docs/electrician/low-voltage-electrician/06-chapter-6-dao-xian-dian-lan-yu-di-ya-xian-lu/readme.html">06 · 导线电缆与低压线路</a> <a class="header-anchor" href="#_06-·-导线电缆与低压线路" aria-label="Permalink to &quot;[06 · 导线电缆与低压线路](/electrician/low-voltage-electrician/06-chapter-6-dao-xian-dian-lan-yu-di-ya-xian-lu/readme)&quot;">​</a></h3><p>6.1 导线的种类与型号 · 6.2 电缆的种类与选用 · 6.3 导线截面的选择 · 6.4 低压线路的敷设与连接</p><h3 id="_07-·-变压器" tabindex="-1"><a href="/some-docs/electrician/low-voltage-electrician/07-chapter-7-bian-ya-qi/readme.html">07 · 变压器</a> <a class="header-anchor" href="#_07-·-变压器" aria-label="Permalink to &quot;[07 · 变压器](/electrician/low-voltage-electrician/07-chapter-7-bian-ya-qi/readme)&quot;">​</a></h3><p>7.1 变压器的工作原理 · 7.2 变压器的结构与分类 · 7.3 变压器的运行与维护 · 7.4 安全隔离变压器</p><h3 id="_08-·-三相异步电动机" tabindex="-1"><a href="/some-docs/electrician/low-voltage-electrician/08-chapter-8-san-xiang-yi-bu-dian-dong-ji/readme.html">08 · 三相异步电动机</a> <a class="header-anchor" href="#_08-·-三相异步电动机" aria-label="Permalink to &quot;[08 · 三相异步电动机](/electrician/low-voltage-electrician/08-chapter-8-san-xiang-yi-bu-dian-dong-ji/readme)&quot;">​</a></h3><p>8.1 电动机的结构 · 8.2 电动机的工作原理 · 8.3 铭牌与接线方式 · 8.4 电动机的启动与控制 · 8.5 电动机的维护与常见故障</p><h3 id="_09-·-低压配电系统" tabindex="-1"><a href="/some-docs/electrician/low-voltage-electrician/09-chapter-9-di-ya-pei-dian-xi-tong/readme.html">09 · 低压配电系统</a> <a class="header-anchor" href="#_09-·-低压配电系统" aria-label="Permalink to &quot;[09 · 低压配电系统](/electrician/low-voltage-electrician/09-chapter-9-di-ya-pei-dian-xi-tong/readme)&quot;">​</a></h3><p>9.1 电力系统与低压配电概述 · 9.2 低压配电系统的接地形式 · 9.3 配电箱与配电柜 · 9.4 电工识图基础</p><h3 id="_10-·-电气照明" tabindex="-1"><a href="/some-docs/electrician/low-voltage-electrician/10-chapter-10-dian-qi-zhao-ming/readme.html">10 · 电气照明</a> <a class="header-anchor" href="#_10-·-电气照明" aria-label="Permalink to &quot;[10 · 电气照明](/electrician/low-voltage-electrician/10-chapter-10-dian-qi-zhao-ming/readme)&quot;">​</a></h3><p>10.1 照明基础知识与质量指标 · 10.2 常用光源与灯具 · 10.3 照明线路的安装 · 10.4 照明常见故障与检修</p><h3 id="_11-·-防雷与接地" tabindex="-1"><a href="/some-docs/electrician/low-voltage-electrician/11-chapter-11-fang-lei-yu-jie-di/readme.html">11 · 防雷与接地</a> <a class="header-anchor" href="#_11-·-防雷与接地" aria-label="Permalink to &quot;[11 · 防雷与接地](/electrician/low-voltage-electrician/11-chapter-11-fang-lei-yu-jie-di/readme)&quot;">​</a></h3><p>11.1 雷电危害与防雷装置 · 11.2 接地与接零保护 · 11.3 接地装置的安装与检测</p><h3 id="_12-·-电气防火防爆与触电急救" tabindex="-1"><a href="/some-docs/electrician/low-voltage-electrician/12-chapter-12-dian-qi-fang-huo-fang-bao-yu-chu-dian-ji-jiu/readme.html">12 · 电气防火防爆与触电急救</a> <a class="header-anchor" href="#_12-·-电气防火防爆与触电急救" aria-label="Permalink to &quot;[12 · 电气防火防爆与触电急救](/electrician/low-voltage-electrician/12-chapter-12-dian-qi-fang-huo-fang-bao-yu-chu-dian-ji-jiu/readme)&quot;">​</a></h3><p>12.1 电气火灾的原因与预防 · 12.2 灭火方法与灭火器使用 · 12.3 触电事故的现场处理 · 12.4 心肺复苏与急救方法</p><h3 id="_13-·-安全作业操作规范" tabindex="-1"><a href="/some-docs/electrician/low-voltage-electrician/13-chapter-13-an-quan-zuo-ye-cao-zuo-gui-fan/readme.html">13 · 安全作业操作规范</a> <a class="header-anchor" href="#_13-·-安全作业操作规范" aria-label="Permalink to &quot;[13 · 安全作业操作规范](/electrician/low-voltage-electrician/13-chapter-13-an-quan-zuo-ye-cao-zuo-gui-fan/readme)&quot;">​</a></h3><p>13.1 安全作业组织措施与技术措施 · 13.2 停电验电装设接地线 · 13.3 常用安全用具与绝缘防护 · 13.4 倒闸操作与监护制度</p><h3 id="_14-·-实操考核与应试技巧" tabindex="-1"><a href="/some-docs/electrician/low-voltage-electrician/14-chapter-14-shi-cao-kao-he-yu-ying-shi-ji-qiao/readme.html">14 · 实操考核与应试技巧</a> <a class="header-anchor" href="#_14-·-实操考核与应试技巧" aria-label="Permalink to &quot;[14 · 实操考核与应试技巧](/electrician/low-voltage-electrician/14-chapter-14-shi-cao-kao-he-yu-ying-shi-ji-qiao/readme)&quot;">​</a></h3><p>14.1 实操考核概述与评分标准 · 14.2 仪表使用实操要点 · 14.3 电动机控制线路实操要点 · 14.4 配电线路与电能表接线实操 · 14.5 安全操作与触电急救实操 · 14.6 理论机考题型与答题技巧</p>',41)])])}const u=e(l,[["render",d]]);export{g as __pageData,u as default};
